const brief = $input.first().json;
if (brief.synthetic !== true || !/^[A-Za-z0-9_\-]{1,120}$/.test(brief.brief_id || '') || !/^[A-Za-z0-9_\-]{1,120}$/.test(brief.article_id || '') || typeof brief.editorial_question !== 'string' || !brief.editorial_question.trim()) {
  throw new Error('Invalid synthetic brief: refusing to continue');
}
return [{json: {
  brief_id: brief.brief_id,
  article_id: brief.article_id,
  status: 'proposal_ready_for_review',
  editorial_direction: {
    angle: 'Automate repetitive preparation, not consequential judgment.',
    opening: 'Begin with a deliberately mundane workflow that contains one high-stakes decision.',
    outline: ['Map the actual work', 'Separate mechanical steps from judgment calls', 'Design the handoff and human review', 'Measure whether the workflow actually improved'],
    research_needed: ['Find credible published examples before drafting']
  },
  synthetic: true
}}];

const proposal = $input.first().json;
if (proposal.synthetic !== true || !proposal.editorial_direction || !Array.isArray(proposal.editorial_direction.outline)) {
  throw new Error('Proposal contract invalid: review cannot proceed');
}
return [{json: {
  ...proposal,
  status: 'awaiting_human_editorial_approval',
  human_review_required: true,
  can_draft: false,
  can_publish: false
}}];
